style.css:
@-moz-document domain("youtube.com") {
/* Change the main progress bar color */
  .ytp-play-progress {
    background-color: #ffcadd !important;
  }

  /* Change the buffered progress bar to a lighter pink (optional) */
  .ytp-load-progress {
    background-color: #ffe6f2 !important;
  }

  /* Change the progress dot (scrubber) color */
  .ytp-scrubber-button {
    background-color: #ffcadd !important;
    border-color: #ffcadd !important;
  }

  /* Optional: volume bar, use same color */
  .ytp-volume-slider-handle,
  .ytp-volume-slider-track,
  .ytp-volume-slider-bar {
    background-color: #ffcadd !important;
  }
}
